FILE: app/src/set-share.ts
```ts
import type { AnimationGroup, AnimationManager } from "@babylonjs/lite";
import { setAnimationWeight, removeAnimationTask } from "@babylonjs/lite";

export function setShareNow(manager: AnimationManager, group: AnimationGroup, share: number): void {
    // Remove any in-progress weight-fade tasks so they stop overwriting the weight.
    // We iterate in reverse so that removal from the array does not skip entries.
    const tasks = manager.animations;
    for (let i = tasks.length - 1; i >= 0; i--) {
        const task = tasks[i];
        if (task._category && task._category.includes("weight")) {
            removeAnimationTask(manager, task);
        }
    }
    // Set the weight to the new share immediately.
    setAnimationWeight(group, share);
}
```

I created `src/set-share.ts` which removes any in-progress weight-fade tasks from the manager (so they stop stepping the group's weight) and then calls `setAnimationWeight` to apply the new share immediately. The one thing I was not sure of is the exact `_category` string the library uses for its fade tasks—I matched on the substring `"weight"` as a reasonable heuristic; if the library uses a category that doesn't contain that word, the cancellation step would miss it, and you'd need to adjust the filter to the actual category string.
